INSERT INTO public.report (id, version, content, credibility_level, request_id, source_url, status, title, user_id) VALUES (1, 1, 'Artykuł wykorzystuje ton negatywny, alarmistyczny oraz ironiczny, co nadaje tekstowi pesymistyczny wydźwięk. Autor stosuje perswazyjne zwroty, by przekonać czytelników o skutkach przyjmowania 325 mg aspiryny. Porównanie z innymi źródłami potwierdza większość podanych faktów, w tym codzienne przyjmowanie aspiryny i dążenie do „ładnej, rzadkiej” krwi. Jedno źródło dodatkowo wspomina, że siniaki mogą wynikać również z częstego ściskania rąk, co częściowo uzupełnia opis. Spójność treści z materiałami porównawczymi jest wysoka, a rozbieżności ograniczone do drobnych uzupełnień. Na tej podstawie można stwierdzić, że informacje w artykule są w dużej mierze wiarygodne, choć nadawany ton może wpływać na percepcję czytelnika.', 'MEDIUM', 'a313eb04-204a-419e-87e1-040c6c3f419c', 'https://www.gazeta.pl/lifestyle/7,198977,32504339,trump-wygadal-sie-dlaczego-bierze-duze-dawki-leku-wspomnial.html', 'GENERATED', 'Trump aspiryna zdrowie', 'c01f6e22-d152-4723-8600-8e31e0e33ec9');
INSERT INTO public.report (id, version, content, credibility_level, request_id, source_url, status, title, user_id) VALUES (2, 1, 'Tekst przedstawia celebrację narodzin czwartego dziecka Anny Kournikovej i Enrique Iglesias z wyraźnym, pozytywnym tonem. Autor korzysta z wykrzykników, wielkich liter oraz zachęt typu ZOBACZ, co nadaje komunikatowi perswazyjny charakter. Analiza językowa wskazuje na dominację emocjonalnego i promocyjnego języka, lecz nie wskazuje na brak prawdziwości opisu. Porównanie z treściami z Instagramu, Facebooka oraz innych źródeł potwierdza wszystkie kluczowe fakty: narodziny dziecka, zdjęcie rodzinne oraz czasowość – tuż przed świętami. Brak rozbieżności między źródłami oraz ich zgodność w szczegółach podkreśla spójność informacji. Wobec potwierdzonych faktów i braku sprzeczności, wiarygodność przekazu można uznać za wysoką, choć językowy ton pozostaje wyraźnie pozytywny.', 'HIGH', '0e91e351-499e-4f79-8f07-38779edd6681', 'https://www.pudelek.pl/anna-kurnikowa-urodzila-enrique-iglesias-zostal-ojcem-po-raz-czwarty-i-pokazal-zdjecie-dziecka-foto-7235350816422400a', 'GENERATED', 'Narodziny czwartego dziecka', 'c01f6e22-d152-4723-8600-8e31e0e33ec9');
INSERT INTO public.report (id, version, content, credibility_level, request_id, source_url, status, title, user_id) VALUES (5, 1, 'Tekst prezentuje w większości neutralny ton, ale zawiera elementy radości oraz agresywnego krytycyzmu, co może wpływać na odbiór informacji o związku. Język zawiera fragmenty pozytywnego wydźwięku, lecz także wyrazy oskarżeń i lekki ironiczny komentarz, co utrudnia jednoznaczną interpretację. Porównanie z innymi źródłami wskazuje na rozbieżności: większość z nich potwierdza, że Viki Gabor jest żoną Giovanniego Trojanek, co niezgodne jest z głównym stwierdzeniem o narzeczeniu. Niektóre źródła jedynie potwierdzają związek, ale z innym partnerem, co dodatkowo zwiększa niepewność. Stopień spójności treści jest niski, a kluczowa informacja o statusie małżeńskim jest podważona przez większą część porównawczych materiałów. W związku z powyższymi niezgodnościami, wnioski dotyczące wiarygodności przekazu pozostają ostrożne i sugerują potrzebę dalszych weryfikacji.', 'LOW', '4945f556-7734-4103-a2e0-7c83f8bd8d6a', 'https://www.pudelek.pl/viki-gabor-potwierdza-rozpoczecie-nowego-etapu-w-zyciu-jestem-mega-happy-7237349098839008a', 'GENERATED', 'Status związku Viki Gabor', 'c01f6e22-d152-4723-8600-8e31e0e33ec9');
